excels.excel:

EXPORT WITH SHEET="项目进度计划排期表", HEADER=true,
    MAPPING={"a":"阶段","b":"任务名称","c":"负责人","d":"开始日期","e":"结束日期","f":"工期(天)","g":"完成率"},
    FORMAT={"d":"yyyy-MM-dd","e":"yyyy-MM-dd","f":"0","g":"0%"},
    FORMULAS={
        F2:'E2-D2',F3:'E3-D3',F4:'SUM(F2:F3)',
        F5:'E5-D5',F6:'E6-D6',F7:'SUM(F5:F6)',
        F8:'E8-D8',F9:'E9-D9',F10:'E10-D10',F11:'SUM(F8:F10)',
        F12:'F4+F7+F11',G12:'AVERAGE(G2:G10)'
    },
    STYLE={
        ROW 4:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 11:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 12:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    },
    MERGE:{
        RANGE A2:A3 WITH MERGE_WITH_FIRST,
        RANGE A5:A6 WITH MERGE_WITH_FIRST,
        RANGE A8:A10 WITH MERGE_WITH_FIRST
    }
